// Prepare Search Parameters
const query = $json.query || 'emergency dentists in Austin';
const senderName = $json.senderName || 'Anuj';
const maxResults = $json.maxResults || 15;

// Heuristic extraction of service and city
let primaryService = 'local services';
let city = 'your city';

const inMatch = query.match(/^(.*?)\s+in\s+(.*)$/i);
if (inMatch) {
  primaryService = inMatch[1].trim();
  city = inMatch[2].trim();
} else {
  const parts = query.split(',');
  if (parts.length >= 2) {
    primaryService = parts[0].trim();
    city = parts[1].trim();
  } else {
    primaryService = query;
  }
}

return [{
  json: {
    query,
    primaryService,
    city,
    senderName,
    maxResults,
    encodedQuery: encodeURIComponent(query)
  }
}];

// Unpack leads and benchmark from scraper output
const data = $input.first().json;
const benchmark = data.benchmark || { top3AvgReviews: 120, top3AvgRating: 4.8 };
const leads = data.leads || [];

return leads.map((lead, index) => {
  return {
    json: {
      ...lead,
      benchmark
    }
  };
});

// Calculate Ranking Gap, Practical Timeline (Days) & Action Plan
const item = $json;
const rank = item.currentRank || 1;
const reviews = item.reviewsCount || 0;
const rating = item.rating || 0.0;
const hasWebsite = item.hasRealWebsite || false;
const isUnclaimed = item.isUnclaimed || false;
const gbpUrl = item.gbpUrl || item.mapsUrl || `https://www.google.com/maps?cid=${item.placeCid || ''}`;
const category = item.category || item.primaryService || 'Local Business';
const city = item.city || 'Local Area';
const top3AvgReviews = item.benchmark ? item.benchmark.top3AvgReviews : 100;

const reviewDeficit = Math.max(0, Math.round(top3AvgReviews - reviews));

// Calculate realistic timeline in days
let daysToTop3 = 45;
let practicalTimeline = '30-45 Days (Category Tuning & Review Velocity)';

if (isUnclaimed || !hasWebsite || reviewDeficit > 100) {
  daysToTop3 = 90;
  practicalTimeline = '75-90 Days (Profile Rebuild & Review Acceleration)';
} else if (reviewDeficit > 40) {
  daysToTop3 = 60;
  practicalTimeline = '45-60 Days (Citation Sync & Review Push)';
} else if (rank <= 3) {
  daysToTop3 = 30;
  practicalTimeline = '15-30 Days (Rank Retention & Conversion)';
}

// What lacks
const whatLacks = [];
if (isUnclaimed) {
  whatLacks.push('Profile Ownership Void: Google Business Profile is UNCLAIMED — highly vulnerable and unverified.');
}
if (rank > 3) {
  whatLacks.push(`Rank Deficit: Ranked #${rank}, missing out on top 3-pack search traffic.`);
}
if (reviewDeficit > 0) {
  whatLacks.push(`Review Deficit: Trails Top 3 competitors by ~${reviewDeficit} reviews.`);
}
if (!hasWebsite) {
  whatLacks.push('Domain Penalty: No dedicated website connected to Google Business Profile.');
  whatLacks.push('Conversion Void: Zero digital lead-capture funnel.');
} else {
  whatLacks.push('Schema Deficit: Missing LocalBusiness schema with verified geo-data.');
  whatLacks.push('Lead Automation Gap: Missing automated instant lead-capture response.');
}

// Action Plan
const actionPlan = {
  phase1: 'Days 1-15: Lock in primary GMB category, audit description, trigger automated SMS review campaign.',
  phase2: `Days 16-45: NAP citation syndication across 40 directories, ${hasWebsite ? 'on-page local schema injection' : 'launch mobile lead-capture landing page'}.`,
  phase3: `Days 46-${daysToTop3}: Missed-call text-back automation, review velocity maintenance (8-12/mo).`
};

return {
  json: {
    ...item,
    gbpUrl,
    audit: {
      currentRank: rank,
      reviewDeficit,
      daysToTop3,
      practicalTimeline,
      whatLacks,
      actionPlan
    }
  }
};

// Generate Personalized Cold Email strictly under 100 words adhering to proven template
const item = $json;
const enrichment = item.enrichment || {};
const firstName = (enrichment.firstName && enrichment.firstName !== 'there') ? enrichment.firstName : 'there';
const businessName = item.businessName || 'your business';
const primaryService = item.primaryService || 'services';
const city = item.city || 'your area';
const currentRank = item.currentRank || 8;
const yourName = item.senderName || 'Anuj';

const subject = (firstName !== 'there') 
  ? `${firstName}, check ${businessName} on Google rn` 
  : `Check ${businessName} on Google rn`;

const body = `Hey ${firstName},

Came across ${businessName} while searching for ${primaryService} in ${city} last week.

While looking into it, I noticed you're sitting at #${currentRank} on Google Maps, meaning the top 3 spots are taking virtually all the inbound calls, clicks, and bookings.

Doing the math, being outside the 3-pack is probably costing you dozens of high-value leads every single month.

So, I put together an action plan to get ${businessName} into the Top 3 on Google Maps, plus built out automated lead-capture workflows so you instantly lock in leads and stop wasting hours on repetitive follow-ups and manual tasks.

It's yours. Already mapped out & ready to go.

Reply and I'll hand it over.

Best,

${yourName}`;

// Count words
const wordTokens = body.match(/\b[\w'-]+\b/g) || [];
const wordCount = wordTokens.length;

return {
  json: {
    ...item,
    coldEmail: {
      subject,
      body,
      wordCount,
      isUnder100Words: wordCount < 100,
      recipientEmail: enrichment.primaryEmail || null,
      channel: enrichment.primaryEmail ? 'Email' : (enrichment.instagram ? 'Instagram DM' : (enrichment.facebook ? 'Facebook Messenger' : 'Direct Outreach'))
    }
  }
};
